22:         ("skip", new Regex(@"\bAssert\s*\.\s*Skip(?:When|Unless)?\s*\(|\bSkipException\b|\bSkippable(?:Fact|Theory)\b|\[\s*(?:Fact|Theory)\s*\([^\]]*\bSkip\s*=", RegexOptions.CultureInvariant)),
